                  contactPerson: "Dhirajbhai Vithlani",
                  phone: "+91 98250 88301",
                  billingAddress: "Survey No. 142/2, Gondal Road, Rajkot, Gujarat",
                  gstin: "24AAJCS4412L1ZK"
