  /* ================= 4-CARD DIRECTORY INTERACTION & SEARCH HELPERS ================= */
  copyTextToClipboard(text, label = 'Copied', triggerEl = null) {
    if (!text) return;

    const flashElement = () => {
      if (triggerEl && triggerEl instanceof HTMLElement) {
        triggerEl.classList.add('tf-copied-flash');
        const isPill = triggerEl.classList.contains('tf-copy-btn');
        const originalContent = triggerEl.innerHTML;
        if (isPill) {
          triggerEl.innerHTML = `<i data-lucide="check" class="w-3 h-3 text-emerald-600"></i><span class="text-[10px] font-bold text-emerald-700">✓ Copied!</span>`;
          if (window.lucide) window.lucide.createIcons();
        }
        setTimeout(() => {
          triggerEl.classList.remove('tf-copied-flash');
          if (isPill) {
            triggerEl.innerHTML = tfSanitizeHtml(originalContent);
            if (window.lucide) window.lucide.createIcons();
          }
        }, 1400);
      }
    };

    if (navigator.clipboard && navigator.clipboard.writeText) {
      navigator.clipboard.writeText(text).then(() => {
        this.showToast(`✓ ${label} copied to clipboard!`);
        flashElement();
      }).catch(() => {
        this.fallbackCopyText(text, label, triggerEl);
        flashElement();
      });
    } else {
      this.fallbackCopyText(text, label, triggerEl);
      flashElement();
    }
  }

  fallbackCopyText(text, label, triggerEl = null) {
    const textArea = document.createElement('textarea');
    textArea.value = text;
    textArea.style.position = 'fixed';
    textArea.style.opacity = '0';
    document.body.appendChild(textArea);
    textArea.focus();
    textArea.select();
    try {
      document.execCommand('copy');
      this.showToast(`✓ ${label} copied to clipboard!`);
    } catch (err) {
      this.showToast(`Copy: ${text}`);
    }
    document.body.removeChild(textArea);
  }

  toggleCardKebabMenu(contactId, event) {
    if (event) {
      event.stopPropagation();
      event.preventDefault();
    }
    const allMenus = document.querySelectorAll('.tf-kebab-menu-popup');
    const targetMenu = document.getElementById(`kebab-menu-${contactId}`);
    
    // Close other open kebab menus
    allMenus.forEach(m => {
      if (m !== targetMenu) m.classList.add('hidden');
    });

    if (targetMenu) {
      targetMenu.classList.toggle('hidden');
    }
  }

  closeAllCardKebabMenus() {
    const allMenus = document.querySelectorAll('.tf-kebab-menu-popup');
    allMenus.forEach(m => m.classList.add('hidden'));
  }

  filterPartnerCards(type, filterMode, btn) {
    // Update active chip style in toolbar
    if (btn && btn.parentElement) {
      btn.parentElement.querySelectorAll('.tf-filter-chip').forEach(c => c.classList.remove('active'));
      btn.classList.add('active');
    }

    const cards = document.querySelectorAll(`[data-partner-type="${type}"]`);
    cards.forEach(card => {
      let visible = true;
      if (filterMode === 'active_orders') {
        const count = parseInt(card.getAttribute('data-active-orders') || '0', 10);
        visible = count > 0;
      } else if (filterMode === 'balance_due') {
        visible = card.getAttribute('data-has-balance') === 'true';
      } else if (filterMode === 'all_clear') {
        visible = card.getAttribute('data-has-balance') === 'false';
      }
      card.style.display = visible ? '' : 'none';
    });
  }

  searchPartnerCards(type, query) {
    const q = (query || '').toLowerCase().trim();
    const cards = document.querySelectorAll(`[data-partner-type="${type}"]`);
    cards.forEach(card => {
      if (!q) {
        card.style.display = '';
        return;
      }
      const name = card.getAttribute('data-name') || '';
      const person = card.getAttribute('data-person') || '';
      const city = card.getAttribute('data-city') || '';
      const cardText = card.innerText.toLowerCase();
      const match = name.includes(q) || person.includes(q) || city.includes(q) || cardText.includes(q);
      card.style.display = match ? '' : 'none';
    });
  }

